mationModule -->\n\nLocationComponent->InformationModule\n\n\n\n\n\nPrivacyPolicyComponent\n\nPrivacyPolicyComponent\n\nInformationModule -->\n\nPrivacyPolicyComponent->InformationModule\n\n\n\n\n\nRemoteLearningComponent\n\nRemoteLearningComponent\n\nInformationModule -->\n\nRemoteLearningComponent->InformationModule\n\n\n\n\n\nReopenningComponent\n\nReopenningComponent\n\nInformationModule -->\n\nReopenningComponent->InformationModule\n\n\n\n\n\nTermsComponent\n\nTermsComponent\n\nInformationModule -->\n\nTermsComponent->InformationModule\n\n\n\n\n\nInformationRoutingModule\n\nInformationRoutingModule\n\nInformationModule -->\n\nInformationRoutingModule->InformationModule\n\n\n\n\n\nSharedModule\n\nSharedModule\n\nInformationModule -->\n\nSharedModule->InformationModule\n\n\n\n\n\n\n    \n    \n    \n        Ampliar\n        Restablecer\n        Alejar\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            Fichero\n        \n        \n            src/app/information/information.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Declaraciones\n                    \n                        \n                            AboutComponent\n                        \n                        \n                            CodeConductComponent\n                        \n                        \n                            CodeConductSchoolComponent\n                        \n                        \n                            InformationComponent\n                        \n                        \n                            LicenseComponent\n                        \n                        \n                            LocationComponent\n                        \n                        \n                            PrivacyPolicyComponent\n                        \n                        \n                            RemoteLearningComponent\n                        \n                        \n                            ReopenningComponent\n                        \n                        \n                            TermsComponent\n                        \n                    \n                \n                \n                    Importa\n                    \n                        \n                            InformationRoutingModule\n                        \n                        \n                            SharedModule\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { CommonModule } from '@angular/common';\n\nimport { InformationRoutingModule } from './information-routing.module';\nimport { INFO_COMPONENTS } from './components';\nimport { INFO_CONTAINERS } from './containers';\nimport { SharedModule } from '../shared/shared.module';\nimport { AlertModule } from 'ngx-bootstrap/alert';\n\n\n@NgModule({\n  declarations: [\n    ...INFO_COMPONENTS, ...INFO_CONTAINERS],\n  imports: [\n    SharedModule,\n    InformationRoutingModule,\n    AlertModule\n  ], providers: []\n})\nexport class InformationModule { }\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         comparación de resultados \"\"\n        \n    \n    \n        No hay resultados que coincidan \"\"\n    \n\n"},"modules/InformationRoutingModule.html":{"url":"modules/InformationRoutingModule.html","title":"module - InformationRoutingModule","body":"\n                   \n\n\n\n\n    Módulos\n    InformationRoutingModule\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            Fichero\n        \n        \n            src/app/information/information-routing.module.ts\n        \n\n\n\n\n\n        \n            \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { RouterModule, Routes } from '@angular/router';\nimport { NotFoundComponent } from '@rds-shared/components';\nimport { AboutComponent, ReopenningComponent, RemoteLearningComponent, PrivacyPolicyComponent, LocationComponent, LicenseComponent, CodeConductComponent, CodeConductSchoolComponent, TermsComponent } from './components';\nimport { InformationComponent } from './containers';\n\nconst routes: Routes = [\n  { path: '', component: InformationComponent },\n  {\n    path: 'about',\n    component: AboutComponent,\n    data: { breadcrumb: '¿Quiénes somos?' },\n  },\n  {\n    path: 'reopenning',\n    component: ReopenningComponent,\n    data: { breadcrumb: 'Reapertura' },\n  },\n  {\n    path: 'remote-learning',\n    component: RemoteLearningComponent,\n    data: { breadcrumb: 'Educación a distancia' },\n  },\n  {\n    path: 'privacy-policy',\n    component: PrivacyPolicyComponent,\n    data: { breadcrumb: 'Políticas de privacidad' },\n  },\n  { path: 'not-found', component: NotFoundComponent },\n  {\n    path: 'location',\n    component: LocationComponent,\n    data: { breadcrumb: '¿Dónde estamos?' },\n  },\n  { path: 'license', component: LicenseComponent },\n  {\n    path: 'code-conduct',\n    component: CodeConductComponent,\n    data: { breadcrumb: 'Código de conducta' },\n  },\n  { path: 'code-conduct-school', component: CodeConductSchoolComponent },\n  {\n    path: 'terms',\n    component: TermsComponent,\n    data: { breadcrumb: '¿Quiénes somos?' },\n  },\n  { path: '**', component: NotFoundComponent },];\n\n@NgModule({\n  imports: [RouterModule.forChild(routes)],\n  exports: [RouterModule]\n})\nexport class InformationRoutingModule { }\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         comparación de resultados \"\"\n        \n    \n    \n        No hay resultados que coincidan \"\"\n    \n\n"},"components/LayoutComponent.html":{"url":"components/LayoutComponent.html","title":"component - LayoutComponent","body":"\n                   \n\n\n\n\n\n  Componentes\n  \n  LayoutComponent\n\n\n\n        \n         